-- Migration 0046 (task #46, "fix: stored value contradicting its own CI",
-- follow-up #1): persist the ConfidenceBasis ("verified"/"inferred"/
-- "speculative", lib/recommendations/types.ts) resolveConfidence actually
-- used to produce confidence_label, so a legacy row can be told apart
-- from a genuinely evidence-driven one by what it CONTAINS, not by when
-- it was committed -- code reaches prod on deploy, not on commit, so
-- created_at can't reliably tell a row generated by the old static-
-- confidence table (before commit 5fe41c0 shipped to prod) from one
-- generated by the real evidence-driven system after.
--
-- NULLABLE, NO DEFAULT -- deliberately. Every row written before this
-- column existed (every pre-5fe41c0 row, and every row generated in prod
-- between 5fe41c0 shipping and this fix's own deploy) has no honest value
-- to backfill: NULL means "not proven evidence-driven", read at display
-- time by lib/recommendations/confidence-labels.ts's isLegacyConfidence,
-- never by rewriting the stored confidence_label itself.
--
-- A nullable column with no default is a metadata-only change on
-- Postgres (no table rewrite) -- same reasoning as 0044/0045's columns.
--
-- Prod-fix file: db/prod-fixes/0069-action-items-confidence-basis-*.sql
-- (0067/0068 already taken this task; diag-0069 is the read-only
-- recommendation-legacy-marker query, applied/rollback/post-check share
-- the same number for this one column add).
ALTER TABLE action_items ADD COLUMN IF NOT EXISTS confidence_basis text;
